/* Inicio 3D y práctica independiente: no modifica la misión guiada. */
(()=>{'use strict';
const $=id=>document.getElementById(id),button=$('playHomeRover'),dialog=document.createElement('dialog');dialog.className='home-rover-dialog';dialog.setAttribute('aria-labelledby','homeRoverTitle');dialog.innerHTML='<div class="home-rover-toolbar"><h2 id="homeRoverTitle">Practicá un alunizaje con Félicette</h2><button type="button" id="closeHomeRover">Volver al inicio ✕</button></div><iframe title="Juego del rover: Descenso perfecto"></iframe>';document.body.append(dialog);const frame=dialog.querySelector('iframe');
button.onclick=()=>{frame.src='minijuego/descenso.html?embedded=1&practice=1';dialog.showModal();};$('closeHomeRover').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{frame.removeAttribute('src');button.focus({preventScroll:true});});
addEventListener('message',e=>{if(!dialog.open||e.origin!==location.origin||e.source!==frame.contentWindow||e.data?.type!=='lunar-descent-complete'||e.data?.version!==1||e.data?.real!==true)return;dialog.close();let status=$('homeRoverStatus');if(!status){status=document.createElement('p');status.id='homeRoverStatus';status.setAttribute('role','status');button.after(status);}status.textContent='¡Buen alunizaje! Podés volver a jugar o explorar tu primera misión.';});
const canvas=$('homeWorldsCanvas'),host=$('homeWorlds');if(!canvas||!window.THREE)return;let renderer;try{renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});}catch{return;}
renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.75));renderer.outputEncoding=THREE.sRGBEncoding;const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.1,100);camera.position.z=9;scene.add(new THREE.AmbientLight(0xb8d9ff,.42));const light=new THREE.DirectionalLight(0xffffff,1.2);light.position.set(5,2,5);scene.add(light);const loader=new THREE.TextureLoader(),geometry=new THREE.SphereGeometry(1,64,40);const specs=[['assets/earth-home-texture.png',-.0,-2.7,.68,false],['assets/moon-texture.jpg',0,0,1,false],['assets/sun-home-texture.png',0,2.7,.81,true]];const worlds=[];let loaded=0;
for(const [url,y,x,size,emissive]of specs){loader.load(url,async texture=>{texture.encoding=THREE.sRGBEncoding;let shape=geometry;if(x!==0){try{const file=x<0?'earth-home-geometry.json':'sun-home-geometry.json';const r=await fetch('assets/'+file);if(!r.ok)throw Error(file);const d=await r.json();shape=new THREE.BufferGeometry();shape.setAttribute('position',new THREE.Float32BufferAttribute(d.position,3));shape.setAttribute('normal',new THREE.Float32BufferAttribute(d.normal,3));shape.setAttribute('uv',new THREE.Float32BufferAttribute(d.uv,2));shape.setIndex(d.index);shape.center();shape.computeBoundingSphere();const radius=shape.boundingSphere.radius;shape.scale(1/radius,1/radius,1/radius);if(x>0)shape.rotateX(Math.PI/2);texture.flipY=false;}catch{return;}}const material=emissive?new THREE.MeshBasicMaterial({map:texture}):new THREE.MeshStandardMaterial({map:texture,roughness:1});const mesh=new THREE.Mesh(shape,material);mesh.position.set(x,y,0);mesh.scale.setScalar(size);mesh.rotation.y=-.5;worlds.push(mesh);scene.add(mesh);if(++loaded===3){canvas.hidden=false;host.querySelector('.home-worlds-fallback').hidden=true;resize();}},undefined,()=>{});}
let visible=true,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,last=0;function resize(){const r=host.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.position.z=Math.max(7,3.7/(Math.tan(35*Math.PI/360)*camera.aspect));camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(host);new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;}).observe(host);
const motion=$('toggleHomeMotion');function motionLabel(){motion.textContent=paused?'Activar rotación':'Pausar rotación';motion.setAttribute('aria-pressed',String(paused));}motion.onclick=()=>{paused=!paused;motionLabel();};motionLabel();let drag=null;canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;for(const w of worlds){w.rotation.y+=dx*.009;w.rotation.x=Math.max(-.6,Math.min(.6,w.rotation.x+dy*.006));}drag={x:e.clientX,y:e.clientY};});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>drag=null);canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();for(const w of worlds)w.rotation.y+=e.key==='ArrowLeft'?-.15:.15;});
function render(now){requestAnimationFrame(render);const dt=Math.min(.05,(now-last)/1000||0);last=now;if(document.hidden||!visible||$('audienceWelcome').hidden)return;if(!paused&&!drag)for(const w of worlds)w.rotation.y+=dt*.09;renderer.render(scene,camera);}resize();requestAnimationFrame(render);
})();
